const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.on('line', (input) => {
  const [nStr, t] = input.split(' ');
  const n = parseInt(nStr);
  let s = '';

  for (let i = 2; i <= n; i++) {
    if (n % i === 0) {
      for (let j = i - 1; j >= 0; j--) {
        s += t.charAt(j);
      }
      s += t.substring(i);
      t = s;
      s = '';
    }
  }

  console.log(t);
  rl.close();
});
```

